"""
streamlit_app.py — واجهة ومنطق CareerForge مع بعض في ملف واحد.
يستخدم rag/query.py مباشرة (بدون FastAPI ولا Worker ولا Pages منفصلين).

ملحوظة: اسم العرض بس اتغيّر هنا (APP_DISPLAY_NAME تحت) — أسماء الملفات
والفولدرات (rag/, chroma_db/) وأي أكواد تانية لم تتغيّر.
الخلفية مضمّنة داخل الكود نفسه كـ Base64 (صورة المستخدم، مضغوطة إلى JPEG).
"""

import streamlit as st
from rag.query import RagPipeline, query_rag

# ============================================================
# غيّر السطر ده بس لو حابب تغيّر اسم العرض في الواجهة
# ============================================================
APP_DISPLAY_NAME = "Forjenta"
APP_TAGLINE = "Forge your path. Backed by real sources."

st.set_page_config(
    page_title=APP_DISPLAY_NAME,
    page_icon="\U0001F3AF",
    layout="wide",
    initial_sidebar_state="collapsed",
)

# صورة الخلفية (مضغوطة JPEG، مضمّنة كـ Base64 — بدون رفع ملف صورة منفصل)
BG_IMAGE_B64 = ""

# ============================================================
# التصميم (CSS) — خلفية الصورة + طبقة تعتيم + بطاقات زجاجية
# ============================================================
st.markdown(
    f"""
    <style>
    #MainMenu, footer, header {{visibility: hidden;}}

    .stApp {{
        background:
            linear-gradient(135deg, rgba(10,14,20,0.88) 0%, rgba(15,22,33,0.82) 45%, rgba(10,14,20,0.90) 100%),
            url("data:image/jpeg;base64,{BG_IMAGE_B64}");
        background-size: cover;
        background-position: center;
        background-attachment: fixed;
        position: relative;
    }}

    .block-container {{
        position: relative;
        z-index: 1;
        padding-top: 2rem;
        max-width: 1100px;
    }}

    .hero {{
        text-align: center;
        padding: 28px 20px 22px;
        margin-bottom: 22px;
    }}
    .hero h1 {{
        font-size: 2.5rem;
        font-weight: 800;
        background: linear-gradient(90deg, #f2c14e, #e8973a);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        margin-bottom: 6px;
        text-shadow: 0 2px 18px rgba(0,0,0,0.35);
    }}
    .hero p {{
        color: #d7dee8;
        font-size: 1.05rem;
        margin: 0;
    }}

    .glass-card {{
        background: rgba(15,20,28,0.55);
        border: 1px solid rgba(255,255,255,0.12);
        border-radius: 16px;
        padding: 18px 20px;
        backdrop-filter: blur(10px);
        margin-bottom: 14px;
        box-shadow: 0 8px 24px rgba(0,0,0,0.25);
    }}
    .glass-card h4 {{
        color: #f2c14e;
        font-size: 0.95rem;
        margin-bottom: 10px;
    }}
    .glass-card ul {{
        margin: 0; padding-inline-start: 18px; color: #e3e8ef; font-size: 0.85rem;
    }}
    .glass-card li {{ margin-bottom: 6px; }}
    .status-dot {{
        display: inline-block; width: 8px; height: 8px; border-radius: 50%;
        background: #38d99b; margin-inline-end: 6px;
        box-shadow: 0 0 6px #38d99b;
    }}

    .chat-scroll {{ max-height: 55vh; overflow-y: auto; padding-inline-end: 6px; }}
    .msg-row {{ display: flex; margin-bottom: 14px; }}
    .msg-row.user {{ justify-content: flex-end; }}
    .bubble {{
        max-width: 78%;
        padding: 12px 16px;
        border-radius: 14px;
        font-size: 0.92rem;
        line-height: 1.65;
        color: #f2f4f7;
    }}
    .msg-row.user .bubble {{
        background: linear-gradient(135deg, #2f6fed, #1e4fc4);
        border-bottom-left-radius: 4px;
    }}
    .msg-row.assistant .bubble {{
        background: rgba(15,20,28,0.65);
        border: 1px solid rgba(255,255,255,0.10);
        border-bottom-right-radius: 4px;
        backdrop-filter: blur(8px);
    }}
    .src-badge {{
        display: inline-flex; align-items: center; gap: 4px;
        background: rgba(242,193,78,0.14);
        border: 1px solid rgba(242,193,78,0.4);
        color: #f2c14e;
        border-radius: 20px;
        padding: 3px 10px;
        font-size: 0.72rem;
        margin: 6px 6px 0 0;
    }}
    .src-header {{
        font-size: 0.72rem; color: #b9c4d4; margin-top: 8px;
    }}

    div.stButton > button {{
        background: rgba(15,20,28,0.5);
        border: 1px solid rgba(242,193,78,0.4);
        color: #f2c14e;
        border-radius: 20px;
        font-size: 0.82rem;
        padding: 6px 14px;
    }}
    div.stButton > button:hover {{
        background: rgba(242,193,78,0.18);
        border-color: #f2c14e;
    }}

    .stChatInput textarea, .bubble, .glass-card {{ direction: rtl; text-align: right; }}
    </style>
    """,
    unsafe_allow_html=True,
)

# ============================================================
# الهيدر
# ============================================================
st.markdown(
    f"""
    <div class="hero">
        <h1>\U0001F3AF {APP_DISPLAY_NAME}</h1>
        <p>{APP_TAGLINE}</p>
    </div>
    """,
    unsafe_allow_html=True,
)


@st.cache_resource(show_spinner="جاري تحميل قاعدة المعرفة...")
def load_pipeline() -> RagPipeline:
    return RagPipeline(persist_dir="./chroma_db")


pipeline = load_pipeline()

# ============================================================
# تخطيط: بطاقة جانبية + شات
# ============================================================
col_side, col_chat = st.columns([1, 2.2], gap="large")

with col_side:
    st.markdown(
        """
        <div class="glass-card">
            <h4><span class="status-dot"></span>قاعدة المعرفة</h4>
            <ul>
                <li>📄 كتابة السيرة الذاتية</li>
                <li>📄 تحليل الوصف الوظيفي</li>
                <li>📄 المقابلات السلوكية</li>
                <li>📄 المقابلات التقنية وSystem Design</li>
                <li>📄 التفاوض على الراتب</li>
                <li>📄 بناء العلامة الشخصية</li>
                <li>📄 مسارات أدوار البيانات</li>
            </ul>
        </div>
        <div class="glass-card">
            <h4>ℹ️ عن النظام</h4>
            <ul>
                <li>يعتمد على RAG — إجابات من مصادر موثّقة بس</li>
                <li>كل إجابة معاها المصدر والصفحة</li>
                <li>لو المعلومة مش موجودة، بيقولك بصراحة</li>
            </ul>
        </div>
        """,
        unsafe_allow_html=True,
    )

with col_chat:
    if "messages" not in st.session_state:
        st.session_state.messages = []

    suggested = [
        "ما هو أسلوب STAR؟",
        "أدوات مهندس البيانات",
        "التحضير لـ System Design",
        "نصائح للسيرة الذاتية",
    ]

    def render_message(role, content, sources=None):
        cls = "user" if role == "user" else "assistant"
        html = f'<div class="msg-row {cls}"><div class="bubble">{content}'
        if sources:
            html += '<div class="src-header">📎 المصادر:</div>'
            for s in sources:
                pages = s.get("pages", [])
                page_str = f"ص.{pages[0]}" if len(pages) == 1 else f"ص.{pages[0]}-{pages[-1]}"
                html += f'<span class="src-badge">📄 {s["source"]} · {page_str}</span>'
        html += "</div></div>"
        st.markdown(html, unsafe_allow_html=True)

    def ask(question: str):
        st.session_state.messages.append({"role": "user", "content": question})
        with st.spinner("جاري البحث..."):
            result = query_rag(question, pipeline=pipeline)
        st.session_state.messages.append(
            {"role": "assistant", "content": result["answer"], "sources": result["sources"]}
        )

    chat_box = st.container()
    with chat_box:
        st.markdown('<div class="chat-scroll">', unsafe_allow_html=True)
        if not st.session_state.messages:
            render_message("assistant", f"أهلًا 👋 أنا {APP_DISPLAY_NAME}، اسألني عن أي حاجة في قاعدة المعرفة.")
        for msg in st.session_state.messages:
            render_message(msg["role"], msg["content"], msg.get("sources"))
        st.markdown("</div>", unsafe_allow_html=True)

    if not st.session_state.messages:
        cols = st.columns(4)
        for i, q in enumerate(suggested):
            if cols[i].button(q, use_container_width=True):
                ask(q)
                st.rerun()

    if question := st.chat_input("اكتب سؤالك هنا..."):
        ask(question)
        st.rerun()
